templates.body:
index={{var:index}} earliest=-{{var:range}}
| search {{field}} {{op}} ({{iocs}})
| stats count AS lookups, values(answer) AS answers, min(_time) AS first_seen, max(_time) AS last_seen
        BY src, {{field}}
| convert ctime(first_seen) ctime(last_seen)
| sort - lookups

index={{var:index}} earliest=-{{var:range}}
| search {{field}} {{op}} ({{iocs}})
| table _time, host, user, process_name, process, parent_process_name, file_path, {{field}}
| sort - _time
